cat > main.ts <<'EOF'
// Keyed totals: sums signed 64-bit values per key and answers queries.
//
// Keys are compared by their raw bytes, so the input is handled as a byte
// string (one char per byte) rather than decoded text. This keeps distinct
// byte sequences distinct even when they are invalid UTF-8 or would render
// the same after normalization.

const I64_MIN = -(1n << 63n);
const I64_MAX = (1n << 63n) - 1n;
const VALUE_RE = /^[+-]?[0-9]+$/;

type Entry = { total: bigint; overflow: boolean };

/** Map each byte to the char with the same code (lossless, unlike TextDecoder("latin1")). */
function bytesToBinary(bytes: Uint8Array): string {
  let out = "";
  const CHUNK = 0x8000;
  for (let i = 0; i < bytes.length; i += CHUNK) {
    out += String.fromCharCode(...bytes.subarray(i, i + CHUNK));
  }
  return out;
}

function binaryToBytes(s: string): Uint8Array {
  const out = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
  return out;
}

/** Split into lines, accepting LF or CRLF endings and an optional final newline. */
function splitLines(text: string): string[] {
  if (text === "") return [];
  const lines = text.split("\n");
  if (lines[lines.length - 1] === "") lines.pop();
  return lines.map((l) => (l.endsWith("\r") ? l.slice(0, -1) : l));
}

const isBlank = (line: string) => line.trim() === "";

/** Compute the output for the given input file contents. */
export function solve(input: Uint8Array): Uint8Array {
  let text = bytesToBinary(input);
  // Drop a UTF-8 byte order mark.
  if (text.startsWith("\xEF\xBB\xBF")) text = text.slice(3);

  const lines = splitLines(text);
  let sep = lines.findIndex(isBlank);
  let records: string[];
  let queries: string[];
  if (sep >= 0) {
    records = lines.slice(0, sep);
    queries = lines.slice(sep + 1);
  } else if (lines.length > 0 && !lines[0].trim().includes(" ")) {
    // No separator and the first line is a bare key: queries only.
    records = [];
    queries = lines;
  } else {
    records = lines;
    queries = [];
  }

  const totals = new Map<string, Entry>();
  for (const raw of records) {
    const line = raw.trim();
    if (line === "") continue;
    const space = line.indexOf(" ");
    if (space < 0) continue; // malformed record: no value
    const key = line.slice(0, space);
    const valueText = line.slice(space + 1).trim();
    if (!VALUE_RE.test(valueText)) continue; // malformed value
    const value = BigInt(valueText);

    let entry = totals.get(key);
    if (entry === undefined) {
      entry = { total: 0n, overflow: false };
      totals.set(key, entry);
    }
    if (entry.overflow) continue;
    const next = entry.total + value;
    if (value < I64_MIN || value > I64_MAX || next < I64_MIN || next > I64_MAX) {
      entry.overflow = true;
    } else {
      entry.total = next;
    }
  }

  const out: string[] = [];
  for (const raw of queries) {
    const key = raw.trim();
    if (key === "") continue;
    const entry = totals.get(key);
    const result = entry === undefined
      ? "absent"
      : entry.overflow
      ? "overflow"
      : entry.total.toString();
    out.push(`${key}=${result}\n`);
  }
  return binaryToBytes(out.join(""));
}

async function writeAll(bytes: Uint8Array): Promise<void> {
  let written = 0;
  while (written < bytes.length) {
    written += await Deno.stdout.write(bytes.subarray(written));
  }
}

if (import.meta.main) {
  const path = Deno.args[0];
  if (path === undefined) {
    console.error("usage: deno run --allow-read main.ts <input-file>");
    Deno.exit(2);
  }
  let input: Uint8Array;
  try {
    input = await Deno.readFile(path);
  } catch (err) {
    console.error(`cannot read ${path}: ${err instanceof Error ? err.message : err}`);
    Deno.exit(1);
  }
  await writeAll(solve(input));
}
EOF
cat > main_test.ts <<'EOF'
import { solve } from "./main.ts";

const enc = new TextEncoder();
const dec = new TextDecoder();
const run = (s: string | Uint8Array) =>
  dec.decode(solve(typeof s === "string" ? enc.encode(s) : s));

function eq(actual: unknown, expected: unknown) {
  if (actual !== expected) {
    throw new Error(`expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

Deno.test("basic totals, absent, order", () => {
  eq(run("a 1\nb 2\na 3\n\nb\na\nc\na\n"), "b=2\na=4\nc=absent\na=4\n");
});

Deno.test("empty inputs", () => {
  eq(run(""), "");
  eq(run("\n"), "");
  eq(run("a 1\n"), "");
  eq(run("a 1\n\n"), "");
  eq(run("\nx\n"), "x=absent\n");
  eq(run("a 5\n\na"), "a=5\n");
});

Deno.test("CRLF line endings", () => {
  eq(run("a 1\r\na -3\r\n\r\na\r\n"), "a=-2\n");
});

Deno.test("64-bit boundaries", () => {
  eq(run("m 9223372036854775807\n\nm\n"), "m=9223372036854775807\n");
  eq(run("m -9223372036854775808\n\nm\n"), "m=-9223372036854775808\n");
  eq(run("m 9223372036854775807\nm 1\n\nm\n"), "m=overflow\n");
  eq(run("m -9223372036854775808\nm -1\n\nm\n"), "m=overflow\n");
  // Running total leaves the range even though the final sum would fit.
  eq(run("m 9223372036854775807\nm 1\nm -1\n\nm\n"), "m=overflow\n");
  // Order matters: this order never leaves the range.
  eq(run("m 9223372036854775807\nm -1\nm 1\n\nm\n"), "m=9223372036854775807\n");
  // Values beyond 2^53 keep full precision.
  eq(run("m 9007199254740993\nm 2\n\nm\n"), "m=9007199254740995\n");
});

Deno.test("overflow on one key does not affect others", () => {
  eq(run("a 9223372036854775807\na 1\nb 1\n\na\nb\n"), "a=overflow\nb=1\n");
});

Deno.test("unicode keys compared by bytes", () => {
  // Precomposed vs decomposed é are different keys.
  eq(run("café 1\ncafé 2\n日本 3\n\ncafé\ncafé\n日本\n🙂\n"),
    "café=1\ncafé=2\n日本=3\n🙂=absent\n");
});

Deno.test("invalid UTF-8 bytes stay distinct and round-trip", () => {
  const input = new Uint8Array([0xff, 0x20, 0x31, 0x0a, 0xfe, 0x20, 0x32, 0x0a, 0x0a, 0xff, 0x0a, 0xfe, 0x0a]);
  const out = solve(input);
  const expected = new Uint8Array([0xff, 0x3d, 0x31, 0x0a, 0xfe, 0x3d, 0x32, 0x0a]);
  eq(Array.from(out).join(","), Array.from(expected).join(","));
});

Deno.test("keys that look like object properties", () => {
  eq(run("__proto__ 1\nconstructor 2\n\n__proto__\nconstructor\ntoString\n"),
    "__proto__=1\nconstructor=2\ntoString=absent\n");
});
